import sys
import os
import json
import xml.etree.ElementTree as ET
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import List, Dict, Optional

def parse_jobs_xml(xml_file: str) -> List[Dict[str, str]]:
    tree = ET.parse(xml_file)
    root = tree.getroot()
    max_concurrent = int(root.attrib.get('max_concurrent', 0))
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.attrib.get('id', ''),
            'command': job_elem.find('command').text if job_elem.find('command') is not None else ''
        }
        jobs.append(job)
    return jobs, max_concurrent

def parse_completed_json(json_file: str) -> List[str]:
    with open(json_file, 'r') as f:
        return json.load(f)

def execute_job(job: Dict[str, str], completed_ids: set) -> int:
    if job['id'] in completed_ids:
        return 0
    try:
        result = os.system(job['command'])
        return result
    except Exception as e:
        print(f"Error executing job {job['id']}: {e}", file=sys.stderr)
        return 1

def main():
    if not os.path.exists('jobs.xml'):
        print('missing jobs.xml', file=sys.stderr)
        sys.exit(1)

    jobs, max_concurrent = parse_jobs_xml('jobs.xml')
    completed_ids = set()

    if os.path.exists('completed.json'):
        try:
            with open('completed.json', 'r') as f:
                completed_ids = set(json.load(f))
        except json.JSONDecodeError:
            print('Invalid completed.json format', file=sys.stderr)
            sys.exit(1)

    completed_ids = set(completed_ids)

    def process_job(job):
        return execute_job(job, completed_ids)

    with ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = {executor.submit(process_job, job): job for job in jobs}
        for future in as_completed(futures):
            job = futures[future]
            exit_code = future.result()
            print(f"{job['id']} {exit_code}")

    new_completed_ids = set()
    for job in jobs:
        if job['id'] in completed_ids:
            new_completed_ids.add(job['id'])
        else:
            new_completed_ids.add(job['id'])

    with open('completed.json', 'w') as f:
        json.dump(sorted(new_completed_ids), f)

    sys.exit(0)

if __name__ == '__main__':
    main()

import json
import os
import subprocess
import sys
from collections import deque
from xml.etree import ElementTree as ET

def parse_jobs_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    max_concurrent = int(root.attrib.get('max_concurrent', 1))
    jobs = []
    for job_elem in root.findall('job'):
        job_id = job_elem.attrib['id']
        command = job_elem.find('command').text
        jobs.append((job_id, command))
    return max_concurrent, jobs

def load_completed_jobs(completed_file):
    if os.path.exists(completed_file):
        with open(completed_file, 'r') as f:
            return set(json.load(f))
    return set()

def process_jobs(max_concurrent, jobs, completed_jobs):
    job_queue = deque()
    running_processes = deque()
    exit_codes = {}

    for job_id, command in jobs:
        if job_id in completed_jobs:
            exit_codes[job_id] = 0
            continue

        job_queue.append((job_id, command))

    while job_queue or running_processes:
        if len(running_processes) < max_concurrent and job_queue:
            job_id, command = job_queue.popleft()
            process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            running_processes.append(process)

        if running_processes:
            process = running_processes[0]
            stdout, stderr = process.communicate()
            exit_code = process.returncode
            exit_codes[process.args[0].split()[0]] = exit_code

            if exit_code == 0:
                running_processes.popleft()

    return exit_codes

def update_completed_json(completed_file, original_completed, new_completed):
    with open(completed_file, 'w') as f:
        json.dump(sorted(original_completed | new_completed), f, indent=2)

def main():
    if not os.path.exists('jobs.xml'):
        print('missing jobs.xml', file=sys.stderr)
        sys.exit(1)

    max_concurrent, jobs = parse_jobs_xml('jobs.xml')
    original_completed = load_completed_jobs('completed.json')

    exit_codes = process_jobs(max_concurrent, jobs, original_completed)

    for job_id, command in jobs:
        print(f"{job_id} {exit_codes.get(job_id, 0)}")

    update_completed_json('completed.json', original_completed, {job_id for job_id, _ in jobs if job_id not in original_completed and exit_codes.get(job_id, 0) == 0})

if __name__ == '__main__':
    main()

import json
import os
import subprocess
import xml.etree.ElementTree as ET
from collections import deque
from typing import List, Dict, Set

def parse_jobs_xml(xml_file: str) -> List[Dict[str, str]]:
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
        max_concurrent = int(root.attrib.get('max_concurrent', 1))
        jobs = []
        for job_elem in root.findall('job'):
            job_id = job_elem.attrib['id']
            command = job_elem.find('command').text
            jobs.append({'id': job_id, 'command': command})
        return jobs, max_concurrent
    except Exception as e:
        print(f"Error parsing {xml_file}: {e}", file=sys.stderr)
        sys.exit(1)

def load_completed_jobs(completed_file: str) -> Set[str]:
    if not os.path.exists(completed_file):
        return set()
    with open(completed_file, 'r') as f:
        try:
            return set(json.load(f))
        except json.JSONDecodeError:
            return set()

def save_completed_jobs(completed_file: str, completed_jobs: List[str]) -> None:
    with open(completed_file, 'w') as f:
        json.dump(completed_jobs, f)

def run_job(job: Dict[str, str], max_concurrent: int, job_queue: deque) -> int:
    process = subprocess.Popen(
        job['command'].split(),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True
    )
    job_queue.append(process)
    return process.poll()

def main():
    xml_file = 'jobs.xml'
    completed_file = 'completed.json'

    if not os.path.exists(xml_file):
        print('missing jobs.xml', file=sys.stderr)
        sys.exit(1)

    jobs, max_concurrent = parse_jobs_xml(xml_file)
    completed_jobs = load_completed_jobs(completed_file)

    # Filter jobs to run
    jobs_to_run = []
    for job in jobs:
        if job['id'] not in completed_jobs:
            jobs_to_run.append(job)

    # Track running processes and their exit codes
    running_processes = deque()
    exit_codes = [None] * len(jobs)

    for job in jobs:
        if job['id'] in completed_jobs:
            exit_codes[jobs.index(job)] = 0
            continue

        if len(running_processes) >= max_concurrent:
            # Wait for a process to finish before starting a new one
            while running_processes and running_processes[0].poll() is not None:
                process = running_processes.popleft()
                exit_codes[jobs.index(job) if job['id'] in {j['id'] for j in jobs_to_run} else jobs.index(job)] = process.poll()

        exit_codes[jobs.index(job)] = run_job(job, max_concurrent, running_processes)

    # Wait for all remaining processes to finish
    while running_processes:
        process = running_processes.popleft()
        exit_codes[jobs.index(job) if job['id'] in {j['id'] for j in jobs_to_run} else jobs.index(job)] = process.poll()

    # Prepare completed_jobs list
    completed_jobs_list = list(completed_jobs)
    for i, job in enumerate(jobs):
        if exit_codes[i] == 0:
            completed_jobs_list.append(job['id'])

    # Print results
    for i, job in enumerate(jobs):
        print(f"{job['id']} {exit_codes[i]}")

    # Save completed_jobs
    save_completed_jobs(completed_file, completed_jobs_list)

if __name__ == "__main__":
    import sys
    main()
